/*!
 * \file ai_infra_aggregate_hidden_tiling.cpp
 * \brief
 */

#include "ai_infra_aggregate_hidden_tiling.h"
#include "log/log.h"
#include "err/ops_err.h"

using namespace ge;
using namespace AscendC;
using std::map;
using std::string;
namespace optiling {

static constexpr int64_t NUM_ZERO = 0;
static constexpr int64_t NUM_ONE = 1;
static constexpr int64_t NUM_TWO = 2;
static constexpr int64_t NUM_THREE = 3;
static constexpr int64_t NUM_FOUR = 4;
static constexpr int64_t NUM_FIVE = 5;
static constexpr int64_t NUM_SIX = 6;
static constexpr int64_t NUM_SEVEN = 7;
static constexpr int64_t NUM_EIGHT = 8;
static constexpr int64_t FOURTY = 40;
static constexpr int64_t FOURTY_EIGHT = 48;

// ------------------算子原型索引常量定义----------------
// Inputs Index
static constexpr int64_t INPUT_INDEX = 0;
static constexpr int64_t WEIGHT_INDEX = 1;
static constexpr int64_t MASK_INDEX = 2;

// Outputs Index
static constexpr int64_t OUTPUT_INDEXER = 0;

// Dim Num
static constexpr int64_t DIM_NUM_TWO = 2;
static constexpr int64_t DIM_NUM_THREE = 3;

// Dim Index
static constexpr int64_t DIM_IDX_ZERO = 0;
static constexpr int64_t DIM_IDX_ONE = 1;
static constexpr int64_t DIM_IDX_TWO = 2;
static constexpr int64_t DIM_IDX_THREE = 3;

// 入参限制常量
static constexpr int64_t S_SIZE_LIMIT = 32 * 1024;  // 32K
static constexpr int64_t B_SIZE_LIMIT = 8;
static constexpr int64_t H_SIZE_UP_LIMIT = 24576;  // 192*128
static constexpr int64_t H_SIZE_DOWN_LIMIT = 384;  // 192*2
static constexpr int64_t W_SIZE_LIMIT = 3;         // 卷积的窗口固定是3
static constexpr int64_t H_SIZE_FULL = 4096;       // UB全载时，H最大是4096

// workspace上预留100M
static constexpr int64_t DEFAULT_WORKSPACE_SIZE = 100 * 1024 * 1024;

// --------------------------AHInfoParser类成员函数定义-------------------------------------
ge::graphStatus AHInfoParser::GetOpName()
{
    if (context_->GetNodeName() == nullptr) {
        OP_LOGE("AiInfraAggregateHidden", "opName got from TilingContext is nullptr");
        return ge::GRAPH_FAILED;
    }
    opName_ = context_->GetNodeName();
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::GetNpuInfo()
{
    platformInfo_ = context_->GetPlatformInfo();
    OP_CHECK_IF(platformInfo_ == nullptr, OP_LOGE(opName_, "GetPlatformInfo is nullptr."), return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo_);
    aivNum_ = static_cast<int64_t>(ascendcPlatform.GetCoreNumAiv());
    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
    OP_CHECK_IF(aicNum == 0 || aivNum_ == 0, OP_LOGE(opName_, "num of core obtained is 0."), return GRAPH_FAILED);
    socVersion_ = ascendcPlatform.GetSocVersion();
    if ((socVersion_ != platform_ascendc::SocVersion::ASCEND910B) &&
        (socVersion_ != platform_ascendc::SocVersion::ASCEND910_93)) {
        OP_LOGE(opName_, "SOC Version[%d] is not support.", (int32_t)socVersion_);
        return GRAPH_FAILED;
    }
    OP_CHECK_IF(context_->GetWorkspaceSizes(1) == nullptr,
        OP_LOGE(opName_, "workSpaceSize got from ge is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(context_->GetRawTilingData() == nullptr,
        OP_LOGE(context_->GetNodeName(), "RawTilingData got from GE context is nullptr."),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckInputValid()
{
    // 1.获取变量相关参数
    opParamInfo_.input.desc = context_->GetInputDesc(INPUT_INDEX);
    opParamInfo_.input.shape = context_->GetInputShape(INPUT_INDEX);
    // 2.检查变量是否存在
    OP_CHECK_IF(opParamInfo_.input.shape == nullptr,
        OP_LOGE(opName_, "Shape of tensor input is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(opParamInfo_.input.desc == nullptr,
        OP_LOGE(opName_, "Desc of tensor input is nullptr"),
        return ge::GRAPH_FAILED);
    // 3.检查变量类型
    inputType_ = opParamInfo_.input.desc->GetDataType();
    OP_CHECK_IF(((inputType_ != ge::DT_FLOAT16) && (inputType_ != ge::DT_BF16)),
        OP_LOGE(opName_, "The data types of the input must be float16 or bfloat16."),
        return ge::GRAPH_FAILED);
    // 4.检查变量Shape的Dim
    int64_t inputShapeDim = opParamInfo_.input.shape->GetStorageShape().GetDimNum();
    int64_t inputExpectShapeDim = DIM_NUM_THREE;
    OP_CHECK_IF(inputShapeDim != inputExpectShapeDim,
        OP_LOGE(
            opName_, "the dim num of input's shape should be %u, but now is %u", inputExpectShapeDim, inputShapeDim),
        return ge::GRAPH_FAILED);
    // 5.检查变量shape大小是否超限 input [S,B,H],
    //  -----------------------check S Size-------------------
    sSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO));
    OP_LOGI(context_->GetNodeName(), "sSize is %d", sSize_);
    OP_CHECK_IF(sSize_ > S_SIZE_LIMIT,
        OP_LOGE(opName_, "the max of S size only support 32K, but now is %d.", sSize_),
        return ge::GRAPH_FAILED);
    // -----------------------check B Size-------------------
    bSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE));
    OP_LOGI(context_->GetNodeName(), "bSize is %d", bSize_);
    OP_CHECK_IF(bSize_ > B_SIZE_LIMIT,
        OP_LOGE(opName_, "the max of batch size only support 8, but now is %d.", bSize_),
        return ge::GRAPH_FAILED);
    // -----------------------check H Size-------------------
    hSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO));
    OP_LOGI(context_->GetNodeName(), "hSize is %d", hSize_);
    OP_CHECK_IF(hSize_ > H_SIZE_UP_LIMIT,
        OP_LOGE(opName_, "the max of H size must smaller than 24576, but now is %d.", hSize_),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(hSize_ < H_SIZE_DOWN_LIMIT,
        OP_LOGE(opName_, "the min of H size must larger than 384, but now is %d.", hSize_),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckWeightValid()
{
    // 1.获取变量相关参数
    opParamInfo_.weight.desc = context_->GetInputDesc(WEIGHT_INDEX);
    opParamInfo_.weight.shape = context_->GetInputShape(WEIGHT_INDEX);
    // 2.检查变量是否存在
    OP_CHECK_IF(opParamInfo_.weight.shape == nullptr,
        OP_LOGE(opName_, "Shape of tensor weight is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(opParamInfo_.weight.desc == nullptr,
        OP_LOGE(opName_, "Desc of tensor weight is nullptr"),
        return ge::GRAPH_FAILED);
    // 3.检查变量类型
    weightType_ = opParamInfo_.weight.desc->GetDataType();
    OP_CHECK_IF((inputType_ != weightType_),
        OP_LOGE(opName_, "The data types of the input and weight must be the same."),
        return ge::GRAPH_FAILED);
    // 4. 检查变量Shape的Dim
    int64_t weightShapeDim = opParamInfo_.weight.shape->GetStorageShape().GetDimNum();
    int64_t weightExpectShapeDim = DIM_NUM_TWO;
    OP_CHECK_IF(weightShapeDim != weightExpectShapeDim,
        OP_LOGE(
            opName_, "the dim num of weight's shape should be %u, but now is %u", weightExpectShapeDim, weightShapeDim),
        return ge::GRAPH_FAILED);
    // 5.检查变量shape大小是否超限,weight [W=3,H]
    //  -----------------------check W Size-------------------
    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != W_SIZE_LIMIT),
        OP_LOGE(opName_, "The window size of convolution must be 3."),
        return ge::GRAPH_FAILED);
    // 6.检查变量shape大小是否与input一致
    //  -----------------------check H Size-------------------
    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != hSize_),
        OP_LOGE(opName_,
            "Input dim 2 and Weight dim 1 is %u, %u respectively, they must be same.",
            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
            opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckMaskValid()
{
    // 1.获取变量相关参数
    opParamInfo_.mask.tensor = context_->GetOptionalInputTensor(MASK_INDEX);
    opParamInfo_.mask.desc = context_->GetOptionalInputDesc(MASK_INDEX);
    // 2.判断可选变量是否存在
    ifMask_ = 0;
    if (opParamInfo_.mask.tensor != nullptr) {
        ifMask_ = 1;
        // 3. 检查变量类型
        OP_CHECK_IF(opParamInfo_.mask.desc->GetDataType() != ge::DT_BOOL,
            OP_LOGE(opName_, "the mask data type only support BOOL"),
            return ge::GRAPH_FAILED);
        // 4. 检查变量Shape的Dim
        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDimNum() != DIM_NUM_TWO),
            OP_LOGE(opName_, "the dim num of mask's shape should be 2"),
            return ge::GRAPH_FAILED);
        // 5.检查变量shape大小是否与input一致,mask [B,S]
        //  -----------------------check B Size-------------------
        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO) != bSize_),
            OP_LOGE(opName_,
                "Input dim 1 and mask dim 0 is %u, %u respectively, they must be same.",
                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO)),
            return ge::GRAPH_FAILED);
        // -----------------------check S Size-------------------
        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE) != sSize_),
            OP_LOGE(opName_,
                "Input dim 0 and mask dim 1 is %u, %u respectively, they must be same.",
                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE)),
            return ge::GRAPH_FAILED);
    }

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CheckOutputValid()
{
    // 1.获取变量相关参数
    opParamInfo_.output.desc = context_->GetOutputDesc(OUTPUT_INDEXER);
    opParamInfo_.output.shape = context_->GetOutputShape(OUTPUT_INDEXER);
    // 2.检查变量是否存在
    OP_CHECK_IF(opParamInfo_.output.shape == nullptr,
        OP_LOGE(opName_, "Shape of tensor output is nullptr"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(opParamInfo_.output.desc == nullptr,
        OP_LOGE(opName_, "Desc of tensor output is nullptr"),
        return ge::GRAPH_FAILED);
    // 3.检查变量类型
    outputType_ = opParamInfo_.output.desc->GetDataType();
    OP_CHECK_IF((inputType_ != outputType_),
        OP_LOGE(opName_, "The data types of the input and output must be the same."),
        return ge::GRAPH_FAILED);
    // 4. 检查变量Shape的Dim
    int64_t outputShapeDim = opParamInfo_.output.shape->GetStorageShape().GetDimNum();
    int64_t outputExpectShapeDim = DIM_NUM_THREE;
    OP_CHECK_IF(outputShapeDim != outputExpectShapeDim,
        OP_LOGE(
            opName_, "the dim num of output's shape should be %u, but now is %u", outputExpectShapeDim, outputShapeDim),
        return ge::GRAPH_FAILED);
    // 5.检查变量shape大小是否与input一致, output [S,B,H]
    //  -----------------------check S Size-------------------
    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != sSize_),
        OP_LOGE(opName_,
            "Input and Output dim 0 is %u, %u respectively, they must be same.",
            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ZERO)),
        return ge::GRAPH_FAILED);
    // -----------------------check B Size-------------------
    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != bSize_),
        OP_LOGE(opName_,
            "Input and Output dim 1 is %u, %u respectively, they must be same.",
            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
        return ge::GRAPH_FAILED);
    // -----------------------check H Size-------------------
    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_TWO) != hSize_),
        OP_LOGE(opName_,
            "Input dim 2 and Output dim 2 is %u, %u respectively, they must be same.",
            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_TWO)),
        return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::GetTilingKey()  // 根据输入数据的类型区分tiling key
{
    tilingKey_ = AGGREGATE_HIDDEN_BF16;
    if (inputType_ == ge::DT_FLOAT16) {
        tilingKey_ = AGGREGATE_HIDDEN_HALF;
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AHInfoParser::CoreSplit()  // 分核计算,如果H能全载就不切H
{
    baseHCnt_ = (hSize_ + H_SIZE_FULL - NUM_ONE) /
                H_SIZE_FULL;  // H切分的份数 = hSize_/4096取上整 baseHCnt_表示一整份H需要用几个核处理
    int64_t flagChange = NUM_ZERO;
    // 调整baseHCnt_使得它能整除aivNum_
    // aivNum_ == 48 | baseHCnt_ == 5
    if (aivNum_ == FOURTY_EIGHT && baseHCnt_ == NUM_FIVE) {
        baseHCnt_ = NUM_SIX;
        flagChange = NUM_ONE;
    }
    // conditions are independent
    // aivNum_ == 40 | baseHCnt_ == 6
    if (aivNum_ == FOURTY && baseHCnt_ == NUM_SIX) {
        baseHCnt_ = NUM_EIGHT;
        flagChange = NUM_ONE;
    }
    // aivNum_ == 40 | baseHCnt_ == 3
    if (aivNum_ == FOURTY && baseHCnt_ == NUM_THREE) {
        baseHCnt_ = NUM_FOUR;
        flagChange = NUM_ONE;
    }
    // else, no assignment

    // 计算baseH_
    if (hSize_ <= H_SIZE_FULL) {
        baseH_ = hSize_;
        baseHTail_ = baseH_;
    } else {
        baseH_ = H_SIZE_FULL;  // baseHCnt_没有被额外修改
        baseHTail_ = hSize_ % baseH_ == NUM_ZERO ? baseH_ : hSize_ % baseH_;
        if (flagChange == NUM_ONE) {  // baseHCnt_被额外修改
            baseH_ = hSize_ / baseHCnt_;
            baseHTail_ = hSize_ % baseHCnt_ == NUM_ZERO ? baseH_ : hSize_ - (baseH_ * (baseHCnt_ - NUM_ONE));
        }
    }

    // 计算baseB_
    int64_t coreNumH = aivNum_ / baseHCnt_;  // coreNumH 表示B还能切多少个核
    baseB_ = (bSize_ + coreNumH - NUM_ONE) / coreNumH;
    if (bSize_ % baseB_ == NUM_ZERO) {
        baseBTail_ = baseB_;
    } else {
        baseBTail_ = bSize_ % baseB_;
    }
    // 计算baseS_
    // 默认不切S
    baseS_ = sSize_;
    baseSTail_ = baseS_;
    baseSCnt_ = NUM_ONE;      // 1表示不切S
    if (baseB_ == NUM_ONE) {  // baseB_大于1，表示B没切完，不切S
        baseSCnt_ = coreNumH / bSize_;
        baseS_ = baseSCnt_ > sSize_ ? NUM_ONE : (sSize_ + baseSCnt_ - NUM_ONE) / baseSCnt_;
        baseSCnt_ = baseSCnt_ > sSize_ ? sSize_ : (sSize_ + baseS_ - 1) / baseS_;
        baseSTail_ = sSize_ % baseSCnt_ == NUM_ZERO ? baseS_ : sSize_ - (baseS_ * (baseSCnt_ - NUM_ONE));
    }

    // 计算blockDim
    baseBCnt_ = (bSize_ + baseB_ - NUM_ONE) / baseB_;
    blockDim_ = baseHCnt_ * baseBCnt_ * baseSCnt_;

    return ge::GRAPH_SUCCESS;
}

void AHInfoParser::GenerateInfo(AHTilingInfo &ahInfo)
{
    ahInfo.opName = opName_;
    ahInfo.platformInfo = platformInfo_;
    ahInfo.opParamInfo = opParamInfo_;
    ahInfo.socVersion = socVersion_;

    ahInfo.ifMask = ifMask_;
    ahInfo.sSize = sSize_;
    ahInfo.bSize = bSize_;
    ahInfo.hSize = hSize_;
    ahInfo.baseS = baseS_;
    ahInfo.baseB = baseB_;
    ahInfo.baseH = baseH_;
    ahInfo.baseSTail = baseSTail_;
    ahInfo.baseBTail = baseBTail_;
    ahInfo.baseHTail = baseHTail_;
    ahInfo.baseSCnt = baseSCnt_;
    ahInfo.baseBCnt = baseBCnt_;
    ahInfo.baseHCnt = baseHCnt_;
    ahInfo.tilingKey = tilingKey_;
    ahInfo.blockDim = blockDim_;
}

void AHInfoParser::DumpTilingInfo(AHTilingInfo &ahInfo)
{
    OP_LOGD(context_->GetNodeName(), "seqLength:  %ld", ahInfo.sSize);
    OP_LOGD(context_->GetNodeName(), "batchSize:  %ld", ahInfo.bSize);
    OP_LOGD(context_->GetNodeName(), "hiddenSize:  %ld", ahInfo.hSize);
    OP_LOGD(context_->GetNodeName(), "baseH:  %ld", ahInfo.baseH);
    OP_LOGD(context_->GetNodeName(), "baseB:  %ld", ahInfo.baseB);
    OP_LOGD(context_->GetNodeName(), "baseS:  %ld", ahInfo.baseS);
    OP_LOGD(context_->GetNodeName(), "baseSTail:  %ld", ahInfo.baseSTail);
    OP_LOGD(context_->GetNodeName(), "baseHTail:  %ld", ahInfo.baseHTail);
    OP_LOGD(context_->GetNodeName(), "baseBTail:  %ld", ahInfo.baseBTail);
    OP_LOGD(context_->GetNodeName(), "baseSCnt:  %ld", ahInfo.baseSCnt);
    OP_LOGD(context_->GetNodeName(), "baseHCnt:  %ld", ahInfo.baseHCnt);
    OP_LOGD(context_->GetNodeName(), "baseBCnt:  %ld", ahInfo.baseBCnt);
    OP_LOGD(context_->GetNodeName(), "tilingKey:  %ld", ahInfo.tilingKey);
    OP_LOGD(context_->GetNodeName(), "ifMask:  %ld", ahInfo.ifMask);
    OP_LOGD(context_->GetNodeName(), "blockDim_:  %ld", ahInfo.blockDim);
}

ge::graphStatus AHInfoParser::ParseAndCheck(AHTilingInfo &ahInfo)
{
    if (ge::GRAPH_SUCCESS != GetOpName() || ge::GRAPH_SUCCESS != GetNpuInfo()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != CheckInputValid() || ge::GRAPH_SUCCESS != CheckWeightValid() ||
        ge::GRAPH_SUCCESS != CheckMaskValid() || CheckOutputValid()) {
        return ge::GRAPH_FAILED;
    }

    if (ge::GRAPH_SUCCESS != GetTilingKey() || ge::GRAPH_SUCCESS != CoreSplit()) {
        return ge::GRAPH_FAILED;
    }

    GenerateInfo(ahInfo);
    DumpTilingInfo(ahInfo);

    return ge::GRAPH_SUCCESS;
}

// --------------------------TilingPrepare函数定义-------------------------------------
static ge::graphStatus TilingPrepareForAiInfraAggregateHidden(gert::TilingParseContext * /* context */)
{
    return ge::GRAPH_SUCCESS;
}

// --------------------------AiInfraAggregateHiddenTiling类成员函数定义-----------------------
ge::graphStatus AiInfraAggregateHiddenTiling::DoTiling(AHTilingInfo *tilingInfo)
{
    // -------------set blockdim-----------------
    context_->SetBlockDim(static_cast<uint32_t>(tilingInfo->blockDim));
    // -------------set workspacesize-----------------
    size_t *workSpaces = context_->GetWorkspaceSizes(1);
    if (workSpaces == nullptr) {
        return ge::GRAPH_FAILED;
    }
    workSpaces[0] = DEFAULT_WORKSPACE_SIZE;

    // -------------set tilingdata-----------------
    tilingData_.set_ifMask(tilingInfo->ifMask);
    tilingData_.set_sSize(tilingInfo->sSize);
    tilingData_.set_bSize(tilingInfo->bSize);
    tilingData_.set_hSize(tilingInfo->hSize);
    tilingData_.set_baseS(tilingInfo->baseS);
    tilingData_.set_baseB(tilingInfo->baseB);
    tilingData_.set_baseH(tilingInfo->baseH);
    tilingData_.set_baseSTail(tilingInfo->baseSTail);
    tilingData_.set_baseBTail(tilingInfo->baseBTail);
    tilingData_.set_baseHTail(tilingInfo->baseHTail);
    tilingData_.set_baseSCnt(tilingInfo->baseSCnt);
    tilingData_.set_baseBCnt(tilingInfo->baseBCnt);
    tilingData_.set_baseHCnt(tilingInfo->baseHCnt);

    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());

    // -------------set tilingkey-----------------
    // 根据输入数据类型的不同区分tiling key
    context_->SetTilingKey(tilingInfo->tilingKey);

    return ge::GRAPH_SUCCESS;
}

// --------------------------Tiling函数定义---------------------------
ge::graphStatus TilingForAiInfraAggregateHidden(gert::TilingContext *context)
{
    OP_CHECK_IF(context == nullptr,
        OPS_REPORT_VECTOR_INNER_ERR("AiInfraAggregateHidden", "Tiling context is null."),
        return ge::GRAPH_FAILED);
    AHTilingInfo ahInfo;
    AHInfoParser ahInfoParser(context);
    if (ahInfoParser.ParseAndCheck(ahInfo) != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    AiInfraAggregateHiddenTiling ahTiling(context);
    return ahTiling.DoTiling(&ahInfo);
}

// --------------------------Tiling函数及TilingPrepare函数注册--------
IMPL_OP_OPTILING(AiInfraAggregateHidden)
    .Tiling(TilingForAiInfraAggregateHidden)
    .TilingParse<AiInfraAggregateHiddenCompileInfo>(TilingPrepareForAiInfraAggregateHidden);

}  // namespace optiling

