namespace optiling {
// ------------------公共定义--------------------------
struct TilingRequiredParaInfo {
    const gert::CompileTimeTensorDesc *desc;
    const gert::StorageShape *shape;
};

struct TilingOptionalParaInfo {
    const gert::CompileTimeTensorDesc *desc;
    const gert::Tensor *tensor;
    const gert::StorageShape *shape;
};

// -----------算子TilingData定义---------------
BEGIN_TILING_DATA_DEF(AiInfraAggregateHiddenTilingData)
TILING_DATA_FIELD_DEF(uint8_t, ifMask);
TILING_DATA_FIELD_DEF(int64_t, hSize);
TILING_DATA_FIELD_DEF(int64_t, bSize);
TILING_DATA_FIELD_DEF(int64_t, sSize);
TILING_DATA_FIELD_DEF(int64_t, baseH);
TILING_DATA_FIELD_DEF(int64_t, baseB);
TILING_DATA_FIELD_DEF(int64_t, baseS);
TILING_DATA_FIELD_DEF(int64_t, baseHTail);
TILING_DATA_FIELD_DEF(int64_t, baseBTail);
TILING_DATA_FIELD_DEF(int64_t, baseSTail);
TILING_DATA_FIELD_DEF(int64_t, baseHCnt);
